    private FmcReconstructionControlAccess(FmcInitialization.Context context,BooleanSupplier qualified,FmcPublication.Authority authority)throws Throwable{
        this.context=context;this.qualified=qualified;this.authority=authority;var owner=context.owner("FmcRte");load=method(owner,FmcReconstructionControlPrepare.NAME,void.class,int[].class,String.class);bank=method(owner,FmcReconstructionControlPrepare.BANK,Object.class);state=method(owner,FmcReconstructionControlPrepare.STATE,int[].class);propagate=method(owner,FmcReconstructionActivationPrepare.NAME,void.class);pointers=method(owner,FmcReconstructionControlPrepare.POINTERS,Object[].class);choices=method(owner,FmcReconstructionControlPrepare.CHOICES,int[].class);context.owner("Routes");context.owner("EiuSystem");
        value=method(context.owner("Qs"),FmcReconstructionBanks.VALUE,String.class,Object.class);accepts=method(context.owner("Qs"),FmcReconstructionBanks.ACCEPTS,boolean.class,Object.class,String.class);pending=method(context.owner("Q"),FmcReconstructionBanks.PENDING,boolean.class,Object.class);
    }
    static FmcReconstructionControlAccess bind(FmcInitialization.Context context,BooleanSupplier qualified,FmcPublication.Authority authority)throws Throwable{Objects.requireNonNull(context);Objects.requireNonNull(qualified);Objects.requireNonNull(authority);require(context.current()&&qualified.getAsBoolean(),"worker qualification");var result=new FmcReconstructionControlAccess(context,qualified,authority);require(context.current()&&qualified.getAsBoolean(),"worker lifecycle changed");return result;}
    private static void require(boolean yes,String why){if(!yes)throw new IllegalStateException("FMC control access "+why);}
