    public void validate(FmcNarrowControl.Execution execution)throws Throwable{require(expected==null&&context.current()&&qualified.getAsBoolean(),"one binding/lifecycle");FmcNarrowControl.validate(execution.replacement().before());FmcNarrowControl.validate(execution.beforeExec());boundBank=bank.invokeExact();require(context.owner("Qs").isInstance(boundBank),"exact bank type");int[] fields=(int[])state.invokeExact();var before=execution.replacement().before();require(Arrays.equals(fields,new int[]{before.viewLeft(),before.viewRight(),before.active(),before.pending()})&&before.bank().equals((String)value.invokeExact(boundBank)),"current complete control preimage");require(!(boolean)pending.invokeExact(boundBank)&&(boolean)accepts.invokeExact(boundBank,execution.beforeExec().bank()),"pending/limits before mutation");navigationChoices=(int[])choices.invokeExact();rootPointers=(Object[])pointers.invokeExact();require(navigationChoices.length==3&&rootPointers.length==18,"complete native pointer/choice roster");for(int i=0;i<3;i++)require(context.owner("FmcRte$Rte").isInstance(rootPointers[i]),"current header root type");for(int i=7;i<9;i++)require(context.owner("Routes$RteBody").isInstance(rootPointers[i]),"current body root type");expected=execution;}
    public void verifyPreimage()throws Throwable{require(expected!=null&&context.current()&&qualified.getAsBoolean()&&bank.invokeExact()==boundBank,"control preimage lifecycle/bank");var before=expected.replacement().before();require(Arrays.equals((int[])state.invokeExact(),new int[]{before.viewLeft(),before.viewRight(),before.active(),before.pending()})&&before.bank().equals((String)value.invokeExact(boundBank))&&!(boolean)pending.invokeExact(boundBank),"control preimage changed before mutation");Object[] currentPointers=(Object[])pointers.invokeExact();int[] currentChoices=(int[])choices.invokeExact();require(currentPointers.length==rootPointers.length&&Arrays.equals(currentChoices,navigationChoices),"control pointer/choice preimage roster changed");for(int i=0;i<rootPointers.length;i++)require(currentPointers[i]==rootPointers[i],"control pointer preimage changed");require(context.current()&&qualified.getAsBoolean(),"control preimage lifecycle changed");}
    private boolean pointerState(FmcNarrowControl.State result)throws Throwable{Object[] actual=(Object[])pointers.invokeExact();int[] selected=(int[])choices.invokeExact();require(actual.length==18&&selected.length==3&&selected[0]==navigationChoices[0]&&selected[1]==navigationChoices[1],"current navigation choices preserved");for(int i:new int[]{0,1,2,7,8,10,11,12,13})require(actual[i]==rootPointers[i],"control root/buffer identity changed");Object left=actual[result.viewLeft()],right=actual[result.viewRight()];int cp=selected[0]==1?1:0,fo=selected[1]==0?0:1;return actual[3]==left&&actual[4]==right&&actual[5]==(cp==0?left:right)&&actual[6]==(fo==0?left:right)&&actual[9]==actual[result.active()==1?7:8]&&selected[2]==1&&actual[14]==actual[10+cp]&&actual[15]==actual[10+fo]&&actual[16]==actual[12+cp]&&actual[17]==actual[12+fo];}
    public void propagate(int nativeCount)throws Throwable{check();require(expected!=null&&!propagated&&bank.invokeExact()==boundBank,"one original-produced control propagation");var result=FmcReconstructionActivationPrepare.expected(expected,nativeCount);require(result.bank().equals((String)value.invokeExact(boundBank)),"ordinary EXEC bank differs from qualified activation result");int[] fields={result.viewLeft(),result.viewRight(),result.active(),result.pending()};if(!Arrays.equals((int[])state.invokeExact(),fields)||!pointerState(result)){propagate.invokeExact();check();}require(Arrays.equals((int[])state.invokeExact(),fields)&&pointerState(result)&&result.bank().equals((String)value.invokeExact(boundBank)),"native activation scalar/pointer/bank propagation incomplete");check();propagated=true;}
    public void load(FmcNarrowControl.State content)throws Throwable{check();require(expected!=null&&content.equals(expected.beforeExec())&&bank.invokeExact()==boundBank,"trusted prepared state/bank alias");verifyPreimage();load.invokeExact(new int[]{content.viewLeft(),content.viewRight(),content.active(),content.pending()},content.bank());check();}
